script:
(function () {
  'use strict';
  // Sales tax, three ways (tax rounded to the nearest cent, as on a receipt):
  //   Add tax:     tax = price x rate,            total = price + tax
  //   Remove tax:  price = total / (1 + rate),    tax = total - price
  //   Find rate:   rate = (total - price) / price
  // The rate is the combined state + local rate the user enters; no state rates are built in.
  // Verified (Node, scratch tests, hand-checked): $100 at 6.5% -> tax $6.50, total $106.50;
  //   $106.50 total at 6.5% -> price $100.00, tax $6.50; $100 -> $106.50 gives 6.5%;
  //   $19.99 at 8.875% -> tax $1.77 ($1.774...), total $21.76; $0 price and 0% rate give $0 tax;
  //   total below price and zero price in rate mode show an error. Whole script run under Node
  //   with a stub DOM: no NaN/Infinity.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function cents(x) { return Math.round((x + (x >= 0 ? 1e-9 : -1e-9)) * 100) / 100; }

  function addTax(price, rate) {
    var tax = cents(price * rate);
    return { price: price, tax: tax, total: cents(price + tax), rate: rate };
  }
  function removeTax(total, rate) {
    var price = cents(total / (1 + rate));
    return { price: price, tax: cents(total - price), total: total, rate: rate };
  }
  function findRate(price, total) {
    return { price: price, tax: cents(total - price), total: total, rate: (total - price) / price };
  }

  function readNum(id) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function show(id, on) { var el = document.getElementById(id); if (el) el.hidden = !on; }
  function highlight(id, on) {
    var el = document.getElementById(id);
    if (el && el.classList) el.classList[on ? 'add' : 'remove']('stat-card-highlight');
  }
  function rateText(r) {
    var p = r * 100;
    return (Math.round(p * 1000) / 1000).toString() + '%';
  }

  function update() {
    var modeEl = document.getElementById('stMode');
    var mode = modeEl && ['add', 'remove', 'rate'].indexOf(modeEl.value) !== -1 ? modeEl.value : 'add';
    show('stPriceField', mode !== 'remove');
    show('stTotalField', mode !== 'add');
    show('stRateField', mode !== 'rate');
    highlight('stCardPrice', mode === 'remove');
    highlight('stCardTotal', mode === 'add');
    highlight('stCardRate', mode === 'rate');

    var price = readNum('stPrice'), total = readNum('stTotal'), rate = readNum('stRate');
    var msg = '';
    if (mode === 'add') {
      if (!isFinite(price) || !isFinite(rate) || price < 0 || price > 1e12 || rate < 0 || rate > 100) msg = 'Enter a price of 0 or more and a tax rate from 0 to 100%.';
    } else if (mode === 'remove') {
      if (!isFinite(total) || !isFinite(rate) || total < 0 || total > 1e12 || rate < 0 || rate > 100) msg = 'Enter a total of 0 or more and a tax rate from 0 to 100%.';
    } else if (!isFinite(price) || !isFinite(total) || price <= 0 || total < 0 || price > 1e12 || total > 1e12) {
      msg = 'Enter a price above 0 and the total you paid.';
    } else if (total < price) {
      msg = 'The total including tax cannot be less than the price before tax.';
    }
    var error = document.getElementById('stError');
    if (error) { error.hidden = !msg; error.textContent = msg; }
    if (msg) {
      ['stOutPrice', 'stOutTax', 'stOutTotal', 'stOutRate'].forEach(function (id) { set(id, '–'); });
      set('stSummary', '');
      return;
    }
    var r = mode === 'add' ? addTax(price, rate / 100) : mode === 'remove' ? removeTax(total, rate / 100) : findRate(price, total);
    set('stOutPrice', money.format(r.price));
    set('stOutTax', money.format(r.tax));
    set('stOutTotal', money.format(r.total));
    set('stOutRate', rateText(r.rate));
    set('stSummary', money.format(r.price) + ' + ' + money.format(r.tax) + ' tax at ' + rateText(r.rate) +
      ' = ' + money.format(r.total) + '. Tax is ' + (r.total > 0 ? (r.tax / r.total * 100).toFixed(2) : '0.00') +
      '% of the total paid.');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('stForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
